import CoreGraphics
let minSideInset: CGFloat = 20
let wideLayoutThreshold: CGFloat = 700
let classicFixedWidth: Double = 680
let classicWidthFraction: Double = 0.85

func classic(pageWidth: CGFloat) -> (maxTextWidth: Double, widthFraction: Double) {
    pageWidth >= wideLayoutThreshold ? (classicFixedWidth, classicWidthFraction) : (0, classicWidthFraction)
}
func metrics(totalWidth: CGFloat, maxTextWidth: CGFloat, widthFraction: CGFloat) -> (contentWidth: CGFloat, sideInset: CGFloat) {
    let available = max(0, totalWidth - 2.0 * minSideInset)
    let content = maxTextWidth > 0 ? min(maxTextWidth, available) : available * max(0.5, min(widthFraction, 1.0))
    return (content, minSideInset + max(0, available - content) / 2.0)
}
let c = classic(pageWidth: 1024)
print("classic(1024) =", c)
print("  maxTextWidth == classicFixedWidth ->", c.maxTextWidth == classicFixedWidth)
let m = metrics(totalWidth: 1024, maxTextWidth: c.maxTextWidth, widthFraction: c.widthFraction)
print("metrics =", m)
print("  contentWidth == classicFixedWidth ->", m.contentWidth == classicFixedWidth)
print("  sideInset > minSideInset ->", m.sideInset > minSideInset)
EOF
